class Solution {
public:
     class SegmentTreeAnd
{
    vector<int> arr, tree;
    int n;
    void segBuild(int node, int st, int en)
    {
        if (st > en)
            return;
        if (st == en)
        {
            tree[node] = arr[st];
            return;
        }
        int md = st + (en - st) / 2;
        segBuild(2 * node, st, md);
        segBuild(2 * node + 1, md + 1, en);
        tree[node] = tree[2 * node] & tree[2 * node + 1];
    }
    int segQuery(int node, int st, int en, int l, int r)
    {
        if (st > r || en < l)
            return -1;
        if (st >= l && en <= r)
            return tree[node];
        int md = st + (en - st) / 2;
        int s1 = segQuery(2 * node, st, md, l, r);
        int s2 = segQuery(2 * node + 1, md + 1, en, l, r);
        return s1 & s2;
    }

public:
    SegmentTreeAnd(vector<int> &temp)
    {
        arr = temp;
        n = arr.size();
        tree.resize(4 * n, -1);
        segBuild(1, 0, n - 1);
    }
    int query(int l, int r)
    {
        return segQuery(1, 0, n - 1, l, r);
    }
};


    long long countSubarrays(vector<int>& nums, int k) {
