class Solution:
    # time O(nlogM), space O(n)
    def countSubarrays(self, nums: List[int], k: int) -> int:
        res = 0
        pre = {}
        for x in nums:
            res += x == k
            cur = {x: 1}
            for val, cnt in pre.items():
                and_val = val & x
                if and_val == k:
                    res += cnt
                cur[and_val] = cur.get(and_val, 0) + cnt
            pre = cur
        return res

class Solution {
    public long countSubarrays(int[] nums, int k) {
        long first =  count(nums, k);
        long second =  count(nums, k + 1);
        // System.out.println(first);
        // System.out.println(second);
        return first - second;
    }
    public long count(int [] nums, int k){
        long cnt = 0;
        int n = nums.length;
        int bitCount[] = new int[32];
        int i = 0, j = 0, and = 0;
        while(j < n){
            add(bitCount, nums[j]);
            if(i == j) and = nums[j];
            else and &= nums[j];
            if(and >= k){
                cnt += j - i + 1;
            }
            else{
                // System.out.printf("prev i for k = %d = %d\n",k , i);
                while(i <= j && and < k){
                    remove(bitCount , nums[i]);
                    and = toNumber(bitCount);
                    i++;
                }
                // System.out.println(Arrays.toString(bitCount));
                // System.out.printf("i = %d, j = %d, cnt = %d, and = %d\n", i, j , cnt, and);
                if(i <= j){
                    cnt += j - i + 1;
                }
            }
            j++;
        }

        return cnt;
    }

    public void remove(int bitc[], int num){
        for(int i = 0; i<32;i++){
            if((num &(1<<i)) == 0){
                bitc[i]--;
            }
        }
    }
    public void add(int bitc[], int num){
        for(int i = 0; i<32;i++){
            if((num &(1<<i)) == 0){
                bitc[i]++;
            }
        }
    }

    public int toNumber(int bitc[]){
        int num = 0;
        for(int i = 0; i<32; i++){
            if(bitc[i] == 0) num |= (1<<i);
        }
        return num;
    }
}

