class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        int m = sizeof(int) * 8;

        vector<vector<long long>> dp;
        for (int i = 0; i < n; ++i) {
            dp.emplace_back();
            dp[i].assign(m, 0);
        }

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                bool hasJBit = (nums[i] & (1 << j)) != 0;
                if (hasJBit) {
                    dp[i][j] = (i > 0) ? dp[i - 1][j] + 1 : 1;
                }
            }
        }

        long long result = 0;
        for (int i = 0; i < n; ++i) {
            long long hasKBitsMin = i + 1;
            long long hasUnneededBitsMax = 0;
            for (int j = 0; j < m; ++j) {
                bool kHasJBit = (k & (1 << j)) != 0;
                if (kHasJBit) {
                    hasKBitsMin = min(hasKBitsMin, dp[i][j]);
                } else {
                    hasUnneededBitsMax = max(hasUnneededBitsMax, dp[i][j]);
                }
            }
            if (hasKBitsMin > hasUnneededBitsMax) {
                result += (hasKBitsMin - hasUnneededBitsMax);
            }
        }
        return result;
    }
};

