class Solution {
public:
    long long helper(vector<int>& nums, int k, int start, int end){
        long long count = 0;
        vector<int> bits(30, -1);
        for(int i = start; i <= end; ++i){
            for(int j = 0; j < 30; ++j){
                if(((nums[i] >> j) & 1) == 0){
                    bits[j] = i;
                }
            }

            int pos = i;
            for(int j = 0; j < 30; ++j){
                int soruce = (nums[i] >> j) & 1;
                int target = (k >> j) & 1;
                if(soruce && !target){
                    pos = min(pos, bits[j]);
                }
            }
            if(pos != -1){
                count += (pos - start + 1);
            }
        }
        return count;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        long long res = 0;
        for(int i = 0, j = 0; i < nums.size(); ++i){
            if((nums[i] & k) != k){
                continue;
            }

            j = i;
            while(j + 1 < nums.size() && (nums[j + 1] & k) == k){
                j += 1;
            }
            res += helper(nums, k, i, j);
            i = j;
        }
        return res;
    }
};

class Solution {
public:

    vector<long long> seg;

    void build(long long indx, long long low, long long high, vector<long long> &a)
    {
        if (low == high)
        {
            seg[indx] = a[low];
            return;
        }

        long long mid = (low + high) / 2;
        build(2 * indx + 1, low, mid, a);
        build(2 * indx + 2, mid + 1, high, a);

        seg[indx]=(seg[2*indx+1] & seg[2*indx+2]);
    }

    long long query(long long indx, long long low, long long high, long long l, long long r)
    {
        if (low >= l && high <= r)
        {
            return seg[indx];
        }

        if (low > r || high < l)
        {
            return INT_MAX;
        }
        long long mid = (low + high) / 2;

        long long left = query(2 * indx + 1, low, mid, l, r);
        long long right = query(2 * indx + 2, mid + 1, high, l, r);

        long long ans=(left & right);
        return ans;
    }

    long long countSubarrays(vector<int>& nums, int K) {

        vector<long long> a;

        int n=nums.size();

        seg.resize(4 * n);


        for(int i=0;i<n;i++)
        {
            a.push_back((long long)nums[i]);
        }

        long long k=K;

        build(0,0,n-1,a);

        long long ans=0ll;

        for(int i=0;i<n;i++)
        {
            int l=i;
            int r=n-1;

            int lower_bound=-1;

            while(l<=r)
            {
                int mid=l+(r-l)/2;

                int val=query(0,0,n-1,i,mid);

                if(val==k)
                {
                    lower_bound=mid;
                    r=mid-1;
                }
                else if(val>k)
                {
                   l=mid+1; 
                }
                else
                {
                    r=mid-1;
                }
            }

            if(lower_bound==-1)
            {
                continue;
            }

            l=i;
            r=n-1;
            int upper_bound=-1;

            while(l<=r)
            {
                int mid=l+(r-l)/2;

                int val=query(0,0,n-1,i,mid);

                if(val==k)
                {
                    upper_bound=mid;
                    l=mid+1;
                }
                else if(val>k)
                {
                  l=mid+1; 
                }
                else
                {
                    r=mid-1;
                }
            }

            //cout<<"i="<<i<<"\n";
            ans+=(long long)(upper_bound-lower_bound+1ll);
            // cout<<upper_bound<<"\n";
            // cout<<lower_bound<<"\n";
            // cout<<"ans="<<ans<<"\n";
        }

        return ans;

    }
};

