                var = mid;
            } else {
                hi = mid - 1;
            }
        }
        int num = 0;
        for(int i = 0; i <= 30; i++) {
            int cnt = pref[i][var + 1] - pref[i][idx];
            if(cnt == var - idx + 1) num += (1 << i);
        }
        if(num == k) {
            return var;
        } 
        return -1;
    }
    int frst(vector<int>& a, int& idx, int& k) {
        int n = a.size();
        int lo = idx, hi = n - 1, var = idx;
        while(lo <= hi) {
            int mid = lo + ((hi - lo) >> 1);
            int val = 0;
            for(int i = 0; i <= 30; i++) {
                int cnt = pref[i][mid + 1] - pref[i][idx];
                if(cnt == mid - idx + 1) {
                    val += (1 << i);
                }
            }
            if(val > k) {
                lo = mid + 1;
            } else {
                var = mid;
                hi = mid - 1;
            }
        }
        int num = 0;
        for(int i = 0; i <= 30; i++) {
            int cnt = pref[i][var + 1] - pref[i][idx];
            if(cnt == var - idx + 1) {
                num += (1 << i);
            }
        }
        if(num == k) {
            return var;
        } 
        return -1;
    }
public:
    using ll = long long;
    ll countSubarrays(vector<int>& a, int k) {
        int n = a.size();
        pref.resize(31, vector<int>(n + 1, 0));
        for(int i = 30; i >= 0; i--) {
            for(int j = 0; j < n; j++) {
                pref[i][j + 1] = pref[i][j] + ((a[j]>>i)&1);
            }
        }
        ll ans = 0;
        for(int i = 0; i < n; i++) {
            if(a[i] < k) continue;
            int fr = frst(a, i, k), ls = lst(a, i, k);
            if(fr==-1)
                continue;
            ans += ls - fr + 1;
        }
        return ans;
    }
};

