class SGTree {
    std::vector<int> seg;
public:
    SGTree(int n) {
        seg.resize(4 * n + 1, INT_MAX);
    }

    void build(int ind, int low, int high, std::vector<int>& arr) {
        if (low == high) {
            seg[ind] = arr[low];
            return;
        }

        int mid = (low + high) / 2;
        build(2 * ind + 1, low, mid, arr);
        build(2 * ind + 2, mid + 1, high, arr);
        seg[ind] = (seg[2 * ind + 1] & seg[2 * ind + 2]);
    }

    int query(int ind, int low, int high, int l, int r) {
        if (r < low || high < l) return INT_MAX;
        if (low >= l && high <= r) return seg[ind];

        int mid = (low + high) >> 1;
        int left = query(2 * ind + 1, low, mid, l, r);
        int right = query(2 * ind + 2, mid + 1, high, l, r);
        return (left & right);
    }

    void update(int ind, int low, int high, int i, int val) {
        if (low == high) {
            seg[ind] = val;
            return;
        }

        int mid = (low + high) >> 1;
        if (i <= mid) update(2 * ind + 1, low, mid, i, val);
        else update(2 * ind + 2, mid + 1, high, i, val);
        seg[ind] = (seg[2 * ind + 1] & seg[2 * ind + 2]);
    }
};

class Solution {
    long long f(std::vector<int>& nums, int k) {
        int n = nums.size();
        SGTree sgt(n);
        sgt.build(0, 0, n - 1, nums);
        long long ans = 0;

        for (int i = 0; i < n; i++) {
            int l = 0;
            int h = i;
            int idx = i + 1;

            while (l <= h) {
                int mid = l + (h - l) / 2;
                if (sgt.query(0, 0, n - 1, mid, i) < k) {
                    l = mid + 1;
                } else {
                    idx = mid;
                    h = mid - 1;
                }
            }
            ans += (i - idx + 1);
        }

        return ans;
    }
public:
    long long countSubarrays(std::vector<int>& nums, int k) {
        long long a = f(nums, k + 1);
        long long b = f(nums, k);
        return b - a;
    }
};

