#define ll long long

class SegmentTree {
private:
    vector<int> tree;
    int n;

    void build(const vector<int>& nums, int node, int start, int end) {
        if (start == end) {
            tree[node] = nums[start];
        } else {
            int mid = (start + end) / 2;
            build(nums, 2 * node, start, mid);
            build(nums, 2 * node + 1, mid + 1, end);
            tree[node] = tree[2 * node] & tree[2 * node + 1];
        }
    }

    int query(int node, int start, int end, int l, int r) {
        if (r < start || end < l) {
            return -1;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        int mid = (start + end) / 2;
        int left_query = query(2 * node, start, mid, l, r);
        int right_query = query(2 * node + 1, mid + 1, end, l, r);
        if (left_query == -1) return right_query;
        if (right_query == -1) return left_query;
        return left_query & right_query;
    }

public:
    SegmentTree(const vector<int>& nums) {
        n = nums.size();
        tree.resize(4 * n);
        build(nums, 1, 0, n - 1);
    }

    int query(int l, int r) {
        return query(1, 0, n - 1, l, r);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n = nums.size();
        ll ans = 0;
        SegmentTree segTree(nums);


        for (int i = 0; i < n; i++) {
            int low = i;
            int high = n - 1;

            int ind1 = -1;
            while (low <= high) {
                int mid = low + (high - low) / 2;
                if (segTree.query(i, mid) > k) {
                    low = mid + 1;
                } else {
                    ind1 = mid;
                    high = mid - 1;
                }
            }

            low = i;
            high = n - 1;

            int ind2 = -1;
            while (low <= high) {
                int mid = low + (high - low) / 2;
                if (segTree.query(i, mid) >= k) {
                    ind2 = mid;
                    low = mid + 1;
                } else {
                    high = mid - 1;
                }
            }

            if (ind1 != -1 && ind2 != -1 && segTree.query(i,ind1) == k && segTree.query(i,ind2)== k) {
                ans += ind2 - ind1 + 1;
            }

            // cout<<i<<" "<<ind1<<" "<<ind2<<" "<<ans<<endl;
        }

        return ans;
    }
};

