class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
    long long n = nums.size();
    vector<long long> arr(32, 0);
    int i = 0;
    while (k) {
        arr[i] = (k % 2);
        k = k / 2;
        i++;
    }
    long long closeZero[n][32];
    long long farOne[n][32];
    memset(closeZero, -1, sizeof(closeZero));
    memset(farOne, -1, sizeof(farOne));
    for (int j = 0; j < 32; j++) {
        for (int i = 0; i < n; i++) {
            long long val = (nums[i] & (1LL << j));
            if (val >= 1) {
                farOne[i][j] = i;
                if (i > 0) {
                    if (farOne[i - 1][j] != -1) {
                        farOne[i][j] = farOne[i - 1][j];
                    }
                    closeZero[i][j] = closeZero[i - 1][j];
                }
            } else {
                closeZero[i][j] = i;
            }
        }
    }
    // for (int i = 0; i < n; i++) {
    //     for (int j = 0; j < 1; j++) {
    //         cout << i << " " << j << " " << farOne[i][j] << " " << closeZero[i][j] << endl;
    //     }
    // }

    long long ans = 0;
    for (int i = 0; i < n; i++) {
        long long mi = 0, ma = i;
        for (int j = 0; j < 32; j++) {
            long long val = (nums[i] & (1LL << j));
            if (val >= 1) {
                if (arr[j] == 1) {
                    mi = max(mi, farOne[i][j]);
                } else {
                    ma = min(ma, closeZero[i][j]);
                }
            } else {
                if (arr[j] == 1) {
                    mi = -1;
                    break;
                }
            }
        }
        if (ma != -1 && mi != -1) {
            ans += max(ma - mi + 1, 0LL);
        }
    }
    return ans;
}
};

