class Solution {
public:


    int binK(int i,int j,int n,vector<vector<int>>&bits){


         int low=i,high=n-1;
         int val=0;
         while(low<=high){
            int mid=low+(high-low)/2;

            if(bits[mid][j]-bits[i][j]==mid-i){
                 val=max(val,mid-i+1);
                 low=mid+1;
            }
            else{
                high=mid-1;
            }
         }

         return val;
    }

    int Kmx(int i,int j,int n,vector<vector<int>>&bits){


         int low=i,high=n-1;
         int val=n;
         while(low<=high){
            int mid=low+(high-low)/2;

            if(bits[mid][j]-bits[i][j]==mid-i){
                 low=mid+1;
            }
            else{
                val=min(val,mid-i);
                high=mid-1;
            }
         }

         return val;
    }
    long long countSubarrays(vector<int>& nums, int k) {

         int n=nums.size();


         vector<vector<int>> bits(n,vector<int>(32,0));

         for(int i=0;i<n;i++){

             for(int j=0;j<32;j++){
                 int c=(1LL<<j);

                 if((nums[i]&c)>0) bits[i][j]++;

                 if(i>0) bits[i][j]+=bits[i-1][j];
             }
         }


         long long sum=0;

         for(int i=0;i<n;i++){

             if((nums[i]&k)==k){
                  int kMin=n;
                  int lngMax=0;

                  for(int j=0;j<32;j++){
                      int c=(1LL<<j);

                      if((k&c)>0){
                          kMin=min(kMin,binK(i,j,n,bits));
                      }
                      else if((nums[i]&c)>0){
                          lngMax=max(lngMax,Kmx(i,j,n,bits));
                      }
                  }



                  if(kMin<lngMax && k!=0) continue;
                  else if(k==0){
                       int rem=n-i;
                       if(lngMax==n) continue;
                       sum+=rem-lngMax;
                  }
                  else sum+=(kMin-lngMax);
             }
         }

         return sum;
    }
};

