class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long ans=0;
        int n=nums.size();
        vector<vector<int> > c(n,vector<int>(40,0));
        int start=-1,end=-1;
        for(int i=0;i<n;i++)
        {
            for(int j=0;j<40;j++)
            {
                if((1ll<<j)&nums[i])
                    c[i][j]=1;
                if(i>0)
                    c[i][j]+=c[i-1][j];
            }
            if((nums[i]&k)==k)
            {
                if(start==-1)
                {
                    start=i;
                    end=i;
                }
                else
                    end++;
            }else
            {
                if(start>-1)
                func(start,end,c,k,ans);
                start=-1;
                end=-1;
            }
        }
         if(start>-1)

             func(start,end,c,k,ans);
        return ans;
    }
    void func(int start,int end,vector<vector<int> > &c,int k, long long &ans)
    {
        int mid;
        for(int i=start;i<=end;i++)
        {
            int pos=-1;
            int l=i,r=end;
            while(l<=r)
            {
                mid=(l+r)/2;
                int count=mid-i+1,num=0;
                for(int j=0;j<40;j++)
                {
                    int x=c[mid][j];
                    if(i>0)
                        x-=c[i-1][j];
                    if(x==count)
                        num+=(1ll<<j);

                }
                if(num==k)
                {
                    pos=mid;
                    r=mid-1;
                }
                else
                    l=mid+1;

            }
            if(pos>-1)
            ans+=end-pos+1;
            //cout<<ans;
        }
    }
};

