  class SegmentTree {
    static constexpr int MAX_NODES = 1048576; // Up to 500k array.

    // T[i]: stored value at the ith node of the tree, which represents
    //       a specific calculation on a subrange.
    // T[0]: 0 - M
    // T[1] = 0 - M/2
    // T[2] = M/2+1 - M
    // T[3] = 0 - M/4
    // T[4] = M/4+1 - M/2
    int T[MAX_NODES];

    // Number of leafs (items in the array).
    int n;

    // Set init value for queries.. 0 for sums, large number for mins, etc..
    int init_value;


    public:
    SegmentTree(int n, int init_value) {
        this->n = n;
        this->init_value = init_value;
        for (int i = 0; i < MAX_NODES; i++)
        T[i] = init_value;
    }

    // What to do to indivdual values (what's the operation).
    void set_op(int& target, int val) {
        target = val;  // set value
        target &= val; // add value
    }

    // How to combine two values
    // (e.g. add to keep track of sums, min to keep track of minimums).
    void combine_op(int& target, int left, int right) {
        target = left & right;  // pick min of the two.
    }

    // Update value of element idx with value val.
    void update(int idx, int val) {
        update(0, 0, n - 1, idx, val);
    }

    void update(int root, int start, int end, int idx, int val) {
        if (start == end) {
        set_op(T[root], val);
        return;
        }
        int mid = (start + end) / 2;
        int left = root * 2 + 1;
        int right = root * 2 + 2;
        if (idx <= mid) {
        // Update left tree.
        update(left, start, mid, idx, val);
        } else {
        update(right, mid + 1, end, idx, val);
        }
        combine_op(T[root], T[left], T[right]);
    }

    int query(int start, int end) {
        return query(0, 0, n - 1, start, end);
    }

    int query(int root, int start, int end, int query_start, int query_end) {
        if (query_start > end || query_end < start) // no overlap.
        return init_value;

        if (query_start <= start && query_end >= end) // full overlap.
        return T[root];

        // While there's even a bit of overlap, try subranges.
        int mid = (start + end) / 2;
        int left = root * 2 + 1;
        int right = root * 2 + 2;

        int left_q = query(left, start, mid, query_start, query_end);
        int right_q = query(right, mid + 1, end, query_start, query_end);
        int ans;
        combine_op(ans, left_q, right_q);
        return ans;
    }

    void print() {
        cout << "[";
        for (int i = 0; i < 4 * n; i++) {
        cout << T[i] << ", ";
        }
        cout << "]" << endl;
    }

};


class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        SegmentTree tree(nums.size(), 2147483647);
        for (int i = 0; i < nums.size(); i++) {
            tree.update(i, nums[i]);
        }
        long long ans = 0;
        for (int i = 0; i < nums.size(); i++) {
            int lo = i;
            int hi = nums.size() - 1;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                int val = tree.query(i, mid);
                if (val >= k) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            int right_bound = lo;
            while (right_bound >= i && tree.query(i, right_bound) < k)
              right_bound--;
            if (right_bound < i || tree.query(i, right_bound) != k) {
                continue;
            }
            lo = i, hi = nums.size() - 1;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                int val = tree.query(i, mid);
                if (val > k) {
                    lo = mid + 1;
                } else {
                    hi = mid;
                }
            }
            int left_bound = lo;
            while (left_bound < right_bound && tree.query(i, left_bound) > k)
              left_bound++;
            ans += right_bound - left_bound + 1;
        }
        return ans;
    }
};

