        int LOG = __lg(n) + 1;
        for (int i = 0; i < n; i++) {
            m[i][0] = nums[i];
        }

        for (int j = 1; j < LOG; j++) {
            for (int i = 0; i + (1 << j) - 1 < n; i++) {
                m[i][j] = m[i][j - 1] & m[i+(1<<(j-1))][j - 1];
            }
        }

        int j = 0, l = 0;
        for (int i = 0; i < n; i++) {
            if (j < i) j = i;
            if (l < i) l = i;
            while (j < n && query(i, j) > k) j++;
