#define ll long long
const ll inf = (1ll << 30) - 1;

struct Node {
  ll val;
  Node() : val(inf) {}
  Node(ll v) : val(v) {}
  friend Node merge(Node l, Node r) { return Node(l.val & r.val); }
  void update(ll v) { val = v; }
};

struct SegTree {
  int n;
  vector<Node> seg;
  SegTree(int _n) : n(_n), seg(2 * _n) {}
  template <typename Type> SegTree(vector<Type> a) {
    n = int(a.size());
    seg.resize(2 * n);
    for (int i = 0; i < n; i++)
      seg[i + n] = Node(a[i]);
    for (int i = n - 1; i > 0; i--)
      seg[i] = merge(seg[i << 1], seg[i << 1 | 1]);
  }

  // 0 based-idx -> sgt[i].val = v
  void update(int i, ll v) {
    assert(i >= 0 && i < n);
    for (seg[i += n].update(v); i >>= 1;)
      seg[i] = merge(seg[i << 1], seg[i << 1 | 1]);
  }

  // 0 based-idx -> l and r both inclusive -> sgt[l..r]
  Node query(int l, int r) {
    assert(l >= 0 && r < n);
    Node res_l, res_r;
    for (l += n, r += n + 1; l < r; l >>= 1, r >>= 1) {
      if (l & 1)
        res_l = merge(res_l, seg[l++]);
      if (r & 1)
        res_r = merge(seg[--r], res_r);
    }
    return merge(res_l, res_r);
  }
};


class Solution {
public:
  long long countSubarrays(vector<int> &nums, int k) {
    SegTree sgt(nums);
    int n = nums.size();
    ll ans = 0;
    for (int i = 0; i < n; i++) {
      if (nums[i] >= k) {
        int L = i, R = n;
        while (R > L + 1) {
          int M = (L + R) / 2;

          (sgt.query(i, M).val >= k ? L = M : R = M);
        }
        if (sgt.query(i, L).val != k)
          continue;
        int lst = L;
        L = i - 1, R = n;
        while (R > L + 1) {
          int M = (L + R) / 2;
          (sgt.query(i, M).val > k ? L = M : R = M);
        }
        L++;
        ans += lst - L + 1;
      }
    }
    return ans;
  }
};

