class Solution {
    public long countSubarrays(int[] nums, int k) {
        int n = nums.length;
        long count = 0;

        HashMap<Long, Long> prevResults = new HashMap<>();

        for (int i = 0; i < n; ++i) {
            HashMap<Long, Long> currResults = new HashMap<>();

            // Check if current element itself equals k
            if (nums[i] == k) {
                ++count;
            }

            // Initialize current results map with current element
            currResults.put((long) nums[i], currResults.getOrDefault((long) nums[i], 0L) + 1);

            // Iterate through previous results map
            for (long val : prevResults.keySet()) {
                long newAndResult = val & nums[i];

                // Check if bitwise AND equals k, update count
                if (newAndResult == k) {
                    count += prevResults.get(val);
                }

                // Update current results map with new AND result
                currResults.put(newAndResult, currResults.getOrDefault(newAndResult, 0L) + prevResults.get(val));
            }

            // Update previous results to current results for next iteration
            prevResults = currResults;
        }

        return count;
    }
}

