class SegmentTree {
public:
    vector<int> tree;
    int n;

    SegmentTree(vector<int>& arr)
    {
        n = arr.size();
        tree.resize(4 * n);
        build(arr, 0, 0, n - 1);
    }

    void build(vector<int>& arr, int node, int start, int end)
    {
        if (start == end) {
            tree[node] = arr[start];
        }
        else {
            int mid = (start + end) / 2;
            build(arr, 2 * node + 1, start, mid);
            build(arr, 2 * node + 2, mid + 1, end);

            tree[node] = tree[2 * node + 1] & tree[2 * node + 2];
        }
    }

    int query(int l, int r)
    {
        return query(0, 0, n - 1, l, r);
    }

    int query(int node, int start, int end, int l, int r)
    {
        if (r < start || end < l) {
            return INT_MAX;
        }
        if (l <= start && end <= r) {
            return tree[node];
        }
        int mid = (start + end) / 2;
        int p1 = query(2 * node + 1, start, mid, l, r);
        int p2 = query(2 * node + 2, mid + 1, end, l, r);

        return p1 & p2;
    }
};

class Solution {
public:
    int getLeftBound(SegmentTree &segTree, int start, int k, int n)
    {
        int ans = -1;
        int L = start, R = n - 1;
        while (L <= R)
        {
            int mid = L + (R - L) / 2;
            int value = segTree.query(start, mid);
            if (value == k)
            {
                ans = mid;
                R = mid - 1;
            }
            else if (value < k)
                R = mid - 1;
            else if (value > k)
                L = mid + 1;

            // cout << L << "\t" << mid << "\t" << R << "\t->" << value << endl;
        }

        return ans;
    }

    int getRightBound(SegmentTree &segTree, int start, int k, int n)
    {
        int ans = -1;
        int L = start, R = n - 1;
        while (L <= R)
        {
            int mid = L + (R - L) / 2;
            int value = segTree.query(start, mid);
            if (value == k)
            {
                ans = mid;
                L = mid + 1;
            }
            else if (value < k)
                R = mid - 1;
            else if (value > k)
                L = mid + 1;

            // cout << L << "\t" << mid << "\t" << R << "\t->" << value << endl;
        }

        return ans;
    }

    long long countSubarrays(vector<int> &arr, int k)
    {
        long long ans = 0;
        SegmentTree segTree(arr);
        for (int i = 0; i < arr.size(); i++)
        {
            int left = getLeftBound(segTree, i, k, arr.size());
            int right = getRightBound(segTree, i, k, arr.size());

            if (left == -1 || right == -1)
                continue;

            ans += right - left + 1;

            // cout << left << "\t" << right << endl;

            // break;
        }

        return ans;
    }
};

