        for (int i = 0; i < size; i++) {
            unordered_map<long long, long long> currentResults;
            totalCount += processCurrentElement(array[i], target, previousResults, currentResults);
            previousResults = currentResults;
        }
        return totalCount;
    }

private:
    long long processCurrentElement(int currentElement, int targetValue,
                                    unordered_map<long long, long long>& previousResults,
                                    unordered_map<long long, long long>& currentResults) {
        long long subarrayCount = 0;

        if (currentElement == targetValue) {
            subarrayCount += 1;
        }
        currentResults[currentElement] = 1;

        for (auto& [previousValue, frequency] : previousResults) {
            long long andResult = previousValue & currentElement;
            if (andResult == targetValue) {
                subarrayCount += frequency;
            }
            currentResults[andResult] += frequency;
        }
        return subarrayCount;
    }
};

