    vector<ll> seg;

public:
    SGTree(ll n)
    {
        seg.resize(4 * n + 1);
    }

    void build(ll ind, ll low, ll high, vector<int> &arr)
    {
        if (low == high)
        {
            seg[ind] = arr[low];
            return;
        }

        ll mid = (low + high) / 2;
        build(2 * ind + 1, low, mid, arr);
        build(2 * ind + 2, mid + 1, high, arr);
        seg[ind] = (seg[2 * ind + 1] & seg[2 * ind + 2]);
    }

    ll query(ll ind, ll low, ll high, ll l, ll r)
    {
        // no overlap
        // l r low high or low high l r
        if (r < low || high < l)
            return (1ll<<32)-1;

        // complete overlap
        // [l low high r]
        if (low >= l && high <= r)
            return seg[ind];

        ll mid = (low + high) >> 1;
        ll left = query(2 * ind + 1, low, mid, l, r);
        ll right = query(2 * ind + 2, mid + 1, high, l, r);
        return (left & right);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        ll n=nums.size();

        SGTree seg(n+5);
        seg.build(0,0,n-1,nums);
        ll cnt=0;
        for(int i=0; i<n; i++) {
            ll l=i,r=n-1;
            ll ans=-1;

            while(l<=r) {
                ll mid=(l+r)/2;

                ll val=seg.query(0,0,n-1,i,mid);

                if(val>k) {
                    l=mid+1;
                }
                else if(val<k) {
                    r=mid-1;
                }
                else {
                    ans=mid;
                    r=mid-1;
                }
            }

            if(ans!=-1) {
                // cout<<"ans = "<<ans<<"\n";
                ll val=seg.query(0,0,n-1,i,ans);
                if(val!=k) continue;

                l=i,r=n-1;
                ll ans1=ans;
                // cout<<"l = "<<l<<" r = "<<r<<"\n";
                while(l<=r) {
                    ll mid=(l+r)/2;

                    val=seg.query(0,0,n-1,i,mid);
                    // cout<<"mid = "<<mid<<" valu = "<<val<<"\n";
                    if(val>k) {
                        l=mid+1;
                    }
                    else if(val<k) {
                        r=mid-1;
                    }
                    else {
                        ans1=mid;
                        l=mid+1;
                    }

                }
                // cout<<"ans1 = "<<ans1<<"\n";
                // cout<<"i = "<<i<<" "<<(ans1-ans+1)<<"\n";
                cnt+=(ans1-ans+1);
            }

        }

        return cnt;
    }
};

