class Solution {
    fun countSubarrays(arr: IntArray, k: Int): Long {
        val n = arr.size
        val st = SegmentTree(arr)
        var ans: Long = 0

        for (i in 0 until n) {
            // 0......i
            var low = 0
            var high = i
            var minIdx = -1
            while (low <= high) {
                val mid = low + (high - low) / 2
                val `and` = st.rangeMinimumQueryLazy(mid, i)
                if (`and` < k) {
                    low = mid + 1
                } else if (`and` > k) {
                    high = mid - 1
                } else {
                    minIdx = mid
                    high = mid - 1
                }
            }

            if (minIdx == -1) {
                // nothing
                continue
            }

            // 0......i
            low = 0
            high = i
            var maxIdx = -1
            while (low <= high) {
                val mid = low + (high - low) / 2
                val `and` = st.rangeMinimumQueryLazy(mid, i)
                if (`and` < k) {
                    low = mid + 1
                } else if (`and` > k) {
                    high = mid - 1
                } else {
                    maxIdx = mid
                    low = mid + 1
                }
            }
            ans += maxIdx - minIdx + 1
        }
        return ans
    }
}

class SegmentTree(arr: IntArray) {
    private val segmentTree: IntArray
    private val lazy: IntArray
    private val n: Int

    init {
        n = arr.size
        segmentTree = IntArray(4 * arr.size)
        lazy = IntArray(4 * arr.size)
        for (i in segmentTree.indices) {
            segmentTree[i] = 0
        }
        build(arr, 0, arr.size - 1, 0)
    }

    private fun build(input: IntArray, low: Int, high: Int, pos: Int) {
        if (low == high) {
            segmentTree[pos] = input[low]
            return
        }
        val mid = (low + high) / 2
        build(input, low, mid, 2 * pos + 1)
        build(input, mid + 1, high, 2 * pos + 2)
        segmentTree[pos] = segmentTree[2 * pos + 1] and segmentTree[2 * pos + 2]
    }

    /**
     * Queries given range lazily
     */
    fun rangeMinimumQueryLazy(qlow: Int, qhigh: Int): Int {
        return rangeMinimumQueryLazy(qlow, qhigh, 0, n - 1, 0)
    }

    private fun rangeMinimumQueryLazy(qlow: Int, qhigh: Int, low: Int, high: Int, pos: Int): Int {
        if (low > high) {
            return Int.MAX_VALUE
        }

        // make sure all propagation is done at pos. If not update tree
        // at pos and mark its children for lazy propagation.
        if (lazy[pos] != 0) {
            segmentTree[pos] = segmentTree[pos] and lazy[pos]
            if (low != high) { // not a leaf node
                lazy[2 * pos + 1] = lazy[2 * pos + 1] and lazy[pos]
                lazy[2 * pos + 2] = lazy[2 * pos + 2] and lazy[pos]
            }
            lazy[pos] = 0
        }

        // no overlap
        if (qlow > high || qhigh < low) {
            return Int.MAX_VALUE
        }

        // total overlap
        if (qlow <= low && qhigh >= high) {
            return segmentTree[pos]
        }

        // partial overlap
        val mid = (low + high) / 2
        return rangeMinimumQueryLazy(qlow, qhigh, low, mid, 2 * pos + 1) and rangeMinimumQueryLazy(qlow, qhigh, mid + 1, high, 2 * pos + 2)
    }
}

