class Solution {
public:
    long long countSubarrays(vector<int>& array, int targetValue) {
        int n = array.size();
        long long count = 0;
        unordered_map<long long, long long> previousMap;

        for (int i = 0; i < n; ++i) {
            unordered_map<long long, long long> currentMap;
            initializeAndCheck(array, i, targetValue, count, currentMap);
            processPreviousResults(array, i, targetValue, previousMap, currentMap, count);
            previousMap = currentMap;
        }

        return count;
    }

private:
    void initializeAndCheck(const vector<int>& array, int i, int targetValue, long long& count, unordered_map<long long, long long>& currentMap) {
        if (array[i] == targetValue) {
            ++count;
        }
        currentMap[array[i]] = 1;
    }

    void processPreviousResults(const vector<int>& array, int i, int targetValue, const unordered_map<long long, long long>& previousMap, unordered_map<long long, long long>& currentMap, long long& count) {
        for (const auto& entry : previousMap) {
            long long prevValue = entry.first;
            long long prevFreq = entry.second;
            long long currentAndResult = prevValue & array[i];
            if (currentAndResult == targetValue) {
                count += prevFreq;
            }
            currentMap[currentAndResult] += prevFreq;
        }
    }
};

