class Solution {
using ll = long long;
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int size = nums.size();
        ll ans = 0;
        map<ll, ll> mp;
        for (int ind = 0; ind < size; ++ind) {
            map<ll, ll> temp_map;
            if (nums[ind] == k) ++ans;
            temp_map[nums[ind]] = 1;
            for (map<ll, ll>::iterator it = mp.begin(); it != mp.end(); ++it) {
                ll cur = it->first & nums[ind];
                if (cur == k) {
                    ans += it->second;
                }
                temp_map[cur] += it->second;
            }

            mp = temp_map;
        }
        return ans;
    }
};

