class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int size = nums.size();
        long long total = 0;
        unordered_map<long long, long long> prev;

        for (int i = 0; i < size; ++i) {
            unordered_map<long long, long long> curr;
            calculateAndCount(nums[i], k, prev, curr, total);
            prev = curr;
        }

        return total;
    }

private:
    void calculateAndCount(long long num, int k, unordered_map<long long, long long>& prev,
                           unordered_map<long long, long long>& curr, long long& total) {
        if (num == k) {
            ++total;
        }
        curr[num] += 1;

        for (auto& [val, freq] : prev) {
            long long new_result = val & num;
            if (new_result == k) {
                total += freq;
            }
            curr[new_result] += freq;
        }
    }
};

