class Solution {
public:
    long long countSubarrays(vector<int>& arr, int k) {
        int n = arr.size();
        long long ans = 0;

        // HashMap to store frequency of AND values
        unordered_map<int, int> andMap;

        for (int i = 0; i < n; i++) {
            unordered_map<int, int> newAndMap;
            if (arr[i] == k) {
                ans++;
            }
            // For each starting index i, compute AND for subarrays ending at j (i <= j < n)
            for (auto &entry : andMap) {
                int newAnd = entry.first & arr[i];
                newAndMap[newAnd] += entry.second;
                if (newAnd == k) {
                    ans += entry.second;
                }
            }
            // Include the current element as a subarray itself
            newAndMap[arr[i]]++;

            andMap = newAndMap;
        }

        return ans;
    }
};

