class SegmentTree{
public:
    vector<int> segtree;
    const int M = (1LL << 31) - 1;
    SegmentTree(int n){
        segtree.resize(4*n+1, M);
    }

    void merge(int node,int lo, int hi){
        segtree[node] = (segtree[2*node+1] & segtree[2*node+2]);
    }


    void build(int lo, int hi, vector<int>&v, int node){
        if(lo == hi){
            segtree[node] = v[lo];
            return;
        }

        int mid = lo + (hi - lo)/2;
        build(lo, mid, v, 2*node+1);
        build(mid+1, hi, v, 2*node+2);
        merge(node, lo, hi);
    }

    int find(int l, int r, int node, int lo, int hi){
        if(lo > r || hi < l) return M;
        if(lo >= l && hi <= r) return segtree[node];

        int mid = lo + (hi - lo)/2;
        int L = find(l, r, 2*node+1, lo, mid);
        int R = find(l, r, 2*node+2, mid+1, hi);
        merge(node, lo, hi);

        return (L & R);
    }
}; 

#define ll long long

class Solution {
public:
    long long countSubarrays(vector<int>& v, int k) {
        int n = v.size();

        vector<vector<int>> pre(31, vector<int> (n+1));
        for(int i = 0;i < n;i++){
            for(int j = 0;j < 31;j++){
                if(v[i] >> j & 1){
                    pre[j][i+1] = 1;
                }
            }
        }

        for(int j = 1;j <= n;j++){
            for(int i = 0;i < 31;i++){
                pre[i][j] += pre[i][j-1];
            }
        }

        auto get = [&](int l, int r){
            l++, r++;
            l--;
            int len = (r - l);
            ll ans = 0;
            for(int i = 0;i < 31;i++){
                int cur = pre[i][r] - pre[i][l];
                if(cur == len){
                    ans += (1LL << i);
                }
            }

            return ans;
        };

        auto chk = [&](int l, int r, int k){
            int a = get(l, r);
            return a >= k;
        };

        auto chk1 = [&](int l, int r, int k){
            int a = get(l, r);

            return a <= k;
        };

        ll ans = 0;
        for(int i = 0;i < n;i++){
            int st = i, e = n-1, a1 = -1;
            // highest
            while(st <= e){
                int mid = (st + e)/2;
                if(chk(i, mid, k)){
                    a1 = mid;
                    st = mid+1;
                }
                else{
                    e = mid-1;
                }
            }
            if(a1 == -1 || get(i, a1) != k) continue;

            st = i, e = a1;
            int a2 = -1;
            //lowest
            while(st <= e){
                int mid = (st + e)/2;
                if(chk1(i, mid, k)){
                    a2 = mid;
                    e = mid-1;
                }
                else{
                    st = mid+1;
                }
            }

            ll len = (a1 - a2 + 1);
            ans += len;
        }
        return ans;
    }
};

