class Solution {
public:
    long long countSubarrays(std::vector<int>& nums, int k) {
        long long result = 0;
        std::unordered_map<int, int> count_map;

        for (int num : nums) {
            std::unordered_map<int, int> new_map;

            // Start new subarrays with the current number
            if (num == k) {
                result++;
            }

            // Update the new_map with new subarrays ending at the current number
            for (const auto& entry : count_map) {
                int new_and = entry.first & num;
                if (new_and == k) {
                    result += entry.second;
                }
                new_map[new_and] += entry.second;
            }

            // Include the current number as a new subarray
            new_map[num]++;

            // Merge the new_map back into count_map
            count_map = new_map;
        }

        return result;
    }
};

