struct sparse {
    int n;
    int k;
    vector<vector<int64_t>> sp;

    int logg(int n) { return n ? __builtin_clz(1) - __builtin_clz(n) : -1; }

    int64_t argmin(int64_t a, int64_t b) { return a & b; }

    void precalc() {
        for (int j = 1; j <= k; j++) {
            for (int i = 0; i <= n - (1 << j); i++) {
                sp[i][j] = argmin(sp[i][j - 1], sp[i + (1 << (j - 1))][j - 1]);
            }
        }
    }

    void init(vector<int> a) {
        n = a.size();
        k = logg(n);
        sp.resize(n, vector<int64_t>(k + 1));
        for (int i = 0; i < n; i++) {
            sp[i][0] = a[i];
        }
        precalc();
    }

    int64_t calc(int l, int r) {
        int p = logg(r - l);
        return argmin(sp[l][p], sp[r - (1 << p)][p]);
    }
};
class Solution {
public:
    long long countSubarrays(vector<int> &nums, int k) {
        int64_t n = nums.size();
        sparse sp;
        sp.init(nums);
        int64_t ans = 0;
        auto ok = [&](int64_t i, int64_t x) {
            return sp.calc(i, x + 1) >= k;
        };
        for (int64_t i = 0; i < n; i++) {
            int64_t l = i;
            int64_t r = n - 1;
            int64_t v1 = -1, v2 = -1;
            while (l <= r) {
                int64_t mid = (l + r) / 2;
                if (sp.calc(i, mid + 1) == k) {
                    v1 = mid;
                }
                if (ok(i, mid)) {
                    r = mid - 1;
                } else {
                    l = mid + 1;
                }
            }
            l = i;
            r = n - 1;
            while (l <= r) {
                int64_t mid = (l + r) / 2;
                if (sp.calc(i, mid + 1) == k) {
                    v2 = mid;
                }
                if (sp.calc(i, mid + 1) >= k) {
                    l = mid + 1;
                } else {
                    r = mid - 1;
                }
            }
            // cout << ";;" <<v1 << " " << v2 << "\n";
            int64_t ll1 = i - 1;
            int64_t ll2 = n;
            if (v2 != -1) {
                l = i;
                r = v2;
                while (l <= r) {
                    int64_t mid = (l + r) / 2;
                    if (sp.calc(i, mid + 1) != k) {
                        l = mid + 1;
                        ll1 = mid;
                    } else {
                        r = mid - 1;
                    }
                }
                ll1++;
                l = v2;
                r = n - 1;
                while (l <= r) {
                    int64_t mid = (l + r) / 2;
                    if (sp.calc(i, mid + 1) != k) {
                        r = mid - 1;
                        ll2 = mid;
                    } else {
                        l = mid + 1;
                    }
                }
                ll2--;
                ans += ll2 - ll1 + 1;
                // cout << ll1 << "-" << ll2 << " ";
                continue;
            }
            if (v1 != -1) {
                l = i;
                r = v1;
                while (l <= r) {
                    int64_t mid = (l + r) / 2;
                    if (sp.calc(i, mid + 1) != k) {
                        l = mid + 1;
                        ll1 = mid;
                    } else {
                        r = mid - 1;
                    }
                }
                ll1++;
                l = v1;
