class Solution {
public:
    vector<int> decToBinary(int n) {
        vector<int> a(32, 0);
        for (int i = 31; i >= 0; i--) {
            int k = n >> i;
            if (k & 1)
                a[31 - i] = 1;
            else
                a[31 - i] = 0;
        }
        return a;
    }

    vector<int> zero;
    vector<int> one;
    vector<int> kk;

    int isSame() {
        for (int i = 0; i < 32; i++) {
            if (kk[i]) {
                if (!(one[i] > 0 && zero[i] == 0)) {
                    return 0;
                }
            } else {
                if (!((one[i] > 0 && zero[i]>0) || (one[i]==0))) {
                    return 0;
                }
            }
        }
        return 1;
    }

    long long countSubarrays(vector<int>& nums, int k) {
        long long ans = 0;
        int n = nums.size();
        vector<vector<int>> a(1);

        for (int i = 0; i < n; i++) {
            if ((nums[i] & k) == k) {
                a.back().push_back(nums[i]);
            } else {
                if (!a.back().empty()) {
                    a.push_back({});
                }
            }
        }

        kk = decToBinary(k);
        for (const auto& subarray : a) {

            zero = vector<int>(32, 0);
            one = vector<int>(32, 0);
            int i = 0, j = 0;

            while (true) {
                while (i < subarray.size() && (j==i || !isSame())) {
                    vector<int> res = decToBinary(subarray[i]);
                    for (int k = 0; k < 32; k++) {
                        if (res[k] == 1) {
                            one[k]++;
                        } else {
                            zero[k]++;
                        }
                    }
                    i++;
                }
                if (i!=j && isSame()) {
                    ans += subarray.size() - i + 1;
                }
                else{
                    if (i == subarray.size() || j==subarray.size()) break;
                }

                vector<int> res = decToBinary(subarray[j]);
                for (int k = 0; k < 32; k++) {
                    if (res[k] == 1) {
                        one[k]--;
                    } else {
                        zero[k]--;
                    }
                }
                j++;
                cout<<ans<<endl;
            }
        }
        return ans;
    }
};

