class Solution {
public:
    class SegmentTree {
public:
   vector<int>seg;
   int n;

   SegmentTree(int n)
   {
      seg = vector<int>(4 * n + 1, INT_MAX);
      this->n = n;
   }

   // Tree will constructed using divide and conquere approach
   // It we be constructed Bottoms up using recursion
   void buildTree(vector<int>&arr, int start, int end, int index)
   {
      if (start == end)
      {
         seg[index] = arr[start];
         return;
      }
      int mid = (start + end) / 2;
      buildTree(arr, start, mid, 2 * index);
      buildTree(arr, mid + 1, end, 2 * index + 1);

      /* By this we can find the min of the segment tree by checking the index of child nodes
         with current node
      */
      seg[index] = seg[2 * index] & seg[2 * index + 1];
   }

   int query(int ss, int se, int qs, int qe, int index)
   {
      // Complete Overlap
      if (qs <= ss and qe >= se)
      {
         return seg[index];
      }

      // No overlap
      if (qs > se || qe < ss)
      {
         return INT_MAX;
      }

      // Partial Overlap
      int mid = (ss + se) / 2;
      int left = query(ss, mid, qs, qe, 2 * index);
      int right = query(mid + 1, se, qs, qe, 2 * index + 1);
      return left&right;
   }

   void update(int ss, int se, int i, int val, int index)
   {
      // Where the i do not like in the range i.e No Overlap
      if (i < ss || i > se)return;

      //Complete overlap i.e index found
      if (ss == se)
      {
         seg[index] += val;
         return;
      }

      // otherwise we will come from down to up and update the value
      // if they are updating with new value

      int mid = (ss + se) / 2;
      update(ss, mid, i, val, 2 * index);
      update(mid + 1, se, i, val, 2 * index + 1);

      seg[index] = seg[2 * index] & seg[2 * index + 1];
      return;
   }
   // The worst case complexity for this can be O(n) in some case we to traverse whole tree
   // which will take time of O(n)
   void updateRange(int ss,int se,int l,int r,int val,int index)
   {
      // No overlap
      if(r<ss||l>se)return;

      // In this it is getting overlaped completly hence we are updating the value for the range (each point present in range)
      if(ss==se)
      {
         seg[index]+=val;
         return;
      }
      // Otherwise we will go recursively in down to top manner

      int mid = (ss+se)/2;
      updateRange(ss,mid,l,r,val,2*index);
      updateRange(mid+1,se,l,r,val,2*index+1);

      seg[index] = min(seg[2*index],seg[2*index+1]);
   }

};
