class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        int n=nums.size();
        long long ans=0;
        vector<vector<int>>pf(n+1,vector<int>(31,0));
        for(int i=0;i<n;++i){
            int num=nums[i];
            for(int j=0;j<31;++j){
                if((num&(1<<j))){
                    pf[i][j]=1;
                    if(i>0) pf[i][j]+=pf[i-1][j];
                }
            }
            int othermx=0;
            int mn=1e9;
            int f=0;
            for(int j=0;j<31;++j){
                if((k&(1<<j))){
                    if(pf[i][j]==0){
                        f=1;
                        break;
                    }
                    mn=min(mn,pf[i][j]);
                }
                else{
                    othermx=max(othermx,pf[i][j]);
                }
            }
            // cout<<num<<" ";
            // cout<<mn<<" "<<othermx<<" "<<f<<endl;
            if(f==0){
                if(k==0){
                    ans+=i-othermx+1;
                }
                else if(mn>othermx){
                    ans+=mn-othermx;
                }
            }
        }
        return ans;
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        int n=a.size();
        vector<int> take(n,-1);
        unordered_map<int,vector<int>> mp,prob;
        for (int i=0;i<n;i++){
            bool t=1;
            for (int j=0;j<=30;j++){
                if ((a[i]>>j&1)==0) mp[j].push_back(i);
                if ((a[i]>>j&1)==0 and (k>>j&1)==1) t=0;
                if ((a[i]>>j&1)==1 and (k>>j&1)==0) prob[i].push_back(j);
            }
            if (t) take[i]=1;
        }
        int last=-1;
        for (int i=n-1;i>=0;i--){
            if (take[i]==1 and last==-1) last=i,take[i]=last;
            else if (take[i]==1) take[i]=last;
            else last=-1;
        }
        // for (int i=0;i<n;i++) cout<<take[i]<<" ";
        // cout<<endl;
        long long ans=0;
        for (int i=0;i<n;i++){
            if (take[i]==-1)
                continue;
            int closest=i;
            bool pos=1;
            for (int val:prob[i]){
                int search=lower_bound(mp[val].begin(),mp[val].end(),i)-mp[val].begin();
                if (search==mp[val].size()){
                    pos=0;
                    break;
                }
                closest=max(mp[val][search],closest);
            }
            if (!pos)
                continue;
            ans+=max(take[i]-closest+1,0);
        }
        return ans;

    }
};

