void construct_segment_tree(vector<int>& segtree,
                            vector<int>& a, int n)
{
    // assign values to leaves of the segment tree
    for (int i = 0; i < n; i++)
        segtree[n + i] = a[i];

    /* assign values to internal nodes
    to compute maximum in a given range */
    for (int i = n - 1; i >= 1; i--)
        segtree[i] = max(segtree[2 * i],
                         segtree[2 * i + 1]);
}

void update(vector<int>& segtree, int pos, int value,
            int n)
{
    // change the index to leaf node first
    pos += n;

    // update the value at the leaf node
    // at the exact index
    segtree[pos] = value;

    while (pos > 1) {

        // move up one level at a time in the tree
        pos >>= 1;

        // update the values in the nodes in
        // the next higher level
        segtree[pos] = segtree[2 * pos]&segtree[2 * pos + 1];
    }
}

int range_query(vector<int>& segtree, int left, int
                                                    right,
                int n)
{
    /* Basically the left and right indices will move
        towards right and left respectively and with
        every each next higher level and compute the 
        maximum at each height. */
    // change the index to leaf node first
    left += n;
    right += n;

    // initialize maximum to a very low value
    int ma = INT_MIN;

    while (left < right) {

        // if left index in odd
        if (left & 1) {
            ma = max(ma, segtree[left]);

            // make left index even
            left++;
        }

        // if right index in odd
        if (right & 1) {

            // make right index even
            right--;

            ma = max(ma, segtree[right]);
        }

        // move to the next higher level
        left /= 2;
        right /= 2;
    }
    return ma;
}

#define ll long long
class SegmentTree
{
public:
    vector<ll> segTree;
    ll size = 0;
    ll ID = (1LL << 32) - 1;

    SegmentTree(ll sz)
    {
        segTree.assign(2 * sz, 0);
        size = sz;
    }

    ll join(ll a, ll b)
    {
        return a & b;
    }

    void update(ll idx, ll val)
    {
        segTree[idx += size] = val;
        for (idx >>= 1; idx; idx >>= 1)
            segTree[idx] = join(segTree[idx << 1], segTree[idx << 1 | 1]);
    }

    ll query(ll l, ll r)
    {
        ll leftAns = ID, RightAns = ID;
        for (l += size, r += size + 1; l < r; l >>= 1, r >>= 1)
        {
            if (l & 1)
                leftAns = join(leftAns, segTree[l++]);
            if (r & 1)
                RightAns = join(segTree[--r], RightAns);
        }
        return join(leftAns, RightAns);
    }
};

class Solution {
public:
    long long countSubarrays(vector<int>& a, int k) {
        long long n = a.size();
        SegmentTree segtree(n);
        for (int i = 0; i < n; i++)
            segtree.update(i,a[i]);

        long long solution = 0;
        for (int i = 0; i < n; i++)
        {
            long long lower_bnd = -1, upper_bnd = -1,left=i,right=n-1;

            while (left <= right)
            {
                long long mid = (left + right) >> 1;
                if(segtree.query(i,mid) > k)
                {
                    left = mid + 1;
                }
                else if(segtree.query(i,mid) == k)
                {
                    lower_bnd = mid;
                    right = mid - 1;
                }
                else
                {
                    right = mid - 1;
                }
            }
            left = i, right = n - 1;
            while (left <= right)
            {
                long long mid = (left + right) >> 1;
                if(segtree.query(i,mid) > k)
                {
                    left = mid + 1;
                }
                else if(segtree.query(i,mid) == k)
                {
                    upper_bnd = mid;
                    left = mid + 1;
                }
                else
                {
                    right = mid - 1;
                }
            }
            if(lower_bnd != -1)
                solution += (upper_bnd - lower_bnd + 1);
        }
        return solution;
    }
};

