class SparseTable {
public:
    vector<vector<int>> st;
    vector<int> log;

    SparseTable(vector<int>& v) {
        int n = v.size();
        int maxLog = log2(n) + 1;
        st.assign(n, vector<int>(maxLog));
        log.assign(n + 1, 0);

        for (int i = 2; i <= n; ++i)
            log[i] = log[i / 2] + 1;

        for (int i = 0; i < n; ++i)
            st[i][0] = v[i];

        for (int j = 1; j < maxLog; ++j) {
            for (int i = 0; i + (1 << j) <= n; ++i) {
                st[i][j] = st[i][j - 1] & st[i + (1 << (j - 1))][j - 1];
            }
        }
    }

    int get_and(int L, int R) {
        int j = log[R - L + 1];
        return st[L][j] & st[R - (1 << j) + 1][j];
    }
};

    long long countSubarrays(vector<int>& v, int k) {
        int n = v.size();
        SparseTable st(v);

        long long ans = 0;

