            int lo = 0;
            int hi = n - i - 1;
            long long ans1 = i - 1;
            long long ans2 = i - 1;
            while(lo <= hi){
                int mid = (lo + hi) / 2;
                int h = st.get_and(i,i + mid);
                if(h >= k){
                    ans1 = i + mid;
                    lo = mid + 1;
                }
                else{
                    hi = mid - 1;
                }
            }
            lo = 0;
            hi = n - i - 1;
             while(lo <= hi){
                int mid = (lo + hi) / 2;
                int h = st.get_and(i,i + mid);
                if(h > k){
                    ans2 = i + mid;
                    lo = mid + 1;
                }
                else{
                    hi = mid - 1;
                }
            }
            cout << ans1 << " " << ans2 <<endl;
            ans += (ans1 - ans2);
        }

        return ans;
    }
};

