class Solution {
    public long countSubarrays(int[] nums, int k) {
        long temp = 0;
        long ans= helper(nums,k,temp);
        return ans;
    }

    public long helper(int[] nums, int k, long temp){
        HashMap<Long, Long> map = new HashMap<>();
        long ans = helper2(nums,k,temp,map);
        return ans;
    }
    public long helper2(int[] nums, int k, long temp, HashMap<Long,Long> map){
        for (int i = 0; i < nums.length; i++) {
            if (nums[i] == k) temp++;
            HashMap<Long, Long> map2 = new HashMap<>();
            long j= (long) nums[i];
            map2.put(j, (long) 1);

            for (Map.Entry<Long, Long> e : map.entrySet()) {
                long key = e.getKey();
                long f = e.getValue();
                long c = key & nums[i];
                if (c == k) temp += f;

                map2.put(c, map2.getOrDefault(c, (long) 0) + f);
            }

            map = map2;
        }
        return temp;
    }
}

