class Solution {
public:
    long long countSubarrays(vector<int>& nums, int k) {
        long long res = 0;
        int n = nums.size();
        vector<int> bits(31, -1);
        for(int i = n - 1;i >= 0;i--){
            int num = nums[i];

            map<int, int> m;
            for(int j = 0;j < 31;j++){
                if(bits[j] >= 0){
                    m[bits[j]]++;
                }
            }

            int l = (num == k) ? i : -1;
            int r = n;
            for(auto &[ind, tmp] : m){
                num &= nums[ind];
                if(num < k){
                    r = ind;
                    break;
                }
                else if(num == k && l == -1){
                    l = ind;
                }
            }
            if(l != -1){
                res += r - l;
            }

            for(int j = 0;j < 31;j++){
                if((nums[i] & (1 << j)) == 0){
                    bits[j] = i;
                }
            }

        }
        return res;
    }
};

