        for(int i = 0;i<n;i++){
            unordered_map<long long, long long> mp1;
            if(nums[i] == k){
                res++;
                pref[i]=1;
            }
            mp1[nums[i]] = 1;

            for(auto it : mp){
                long long num = it.first&nums[i];
                if(num == k){
                    res += it.second;
                }
                mp1[num] += it.second; 
                pref[i]++;
            }
            mp = mp1;
            if(pref[i]==k) cnt++;
            res--;
        }


        return res+n;
    }
};

